+            time: e.position,
+            duration: e.duration,
+          };
+        };
+        break;
+
+      case AD_SKIPPED:
+        getEventPayload = e => {
+          adState.clearState();
+          return {
+            time: e.position,
+            duration: e.duration,
+          };
+        };
+        break;
+
+      case AD_ERROR:
