+          const extraPayload = Object.assign({
+            playerErrorCode: e.adErrorCode,
+            vastErrorCode: e.code,
+            errorMessage: e.message,
+            sourceError: e.sourceError
+            // timeout
+          }, adState.getState(), timeState.getState());
+          adState.clearState();
+          return extraPayload;
+        };
+        break;
+
+      case AD_COMPLETE:
+        getEventPayload = e => {
+          adState.clearState();
