+            contentTags: item.tags
+          };
+        };
+        break;
+
+      case BUFFER:
+        getEventPayload = () => timeState.getState();
+        break;
+
+      case TIME:
+        getEventPayload = e => {
+          timeState.updateForEvent(e);
+          return {
+            position: e.position,
+            duration: e.duration
+          };
+        };
+        break;
+
+      case SEEK_START:
+        getEventPayload = e => {
+          const duration = e.duration;
+          const offset = e.offset;
