+    The following video.js events might map to an event in our spec
+    'loadstart',
+      'progress', buffer load ?
+      'suspend',
+      'abort',
+      'error',
+      'emptied',
+      'stalled',
+      'loadedmetadata', meta
+      'loadeddata', meta
